/* ================= HOSTILES METER v1 =================
   The hostiles alive count is a real meter: role
   meter plus aria-label Hostiles alive and
   aria-valuemin 0 and aria-valuemax 5 in the
   #alive markup, with aria-valuenow kept in sync
   in updateCombatHUD beside the textContent
   writer. The sync uses the ariaValueNow IDL
   property, not setAttribute, because the
   headless stub elements have no setAttribute
   method. The count is bounded by the fixed
   5-entry ENEMY_MIX, so the fixed valuemax 5
   is exact. The runtime checks save the current
   enemy states, set the first two enemies dead
   and the rest to wander, call updateCombatHUD,
   then restore the saved states and call it
   again, leaving the harness in its prior
   state. */
{
  const probsHM = consoleProblems.length;
  const linesHM = html.split('\n');
  const lineHasHM = sub => linesHM.filter(l => l.includes(sub)).length;
  check('hostiles: HOSTILES METER v1 header is present exactly once in the game source',
    (html.split('HOSTILES METER v1').length - 1) === 1,
    'n=' + (html.split('HOSTILES METER v1').length - 1));
  const aliveTagHM = (html.match(/<b id="alive"[^>]*>/) || [''])[0];
  check('hostiles: #alive element markup carries role="meter"',
    aliveTagHM.includes('role="meter"'), 'tag=' + aliveTagHM);
  check('hostiles: #alive element markup carries aria-label="Hostiles alive"',
    aliveTagHM.includes('aria-label="Hostiles alive"'), 'tag=' + aliveTagHM);
  check('hostiles: #alive element markup carries aria-valuemin="0"',
    aliveTagHM.includes('aria-valuemin="0"'), 'tag=' + aliveTagHM);
  check('hostiles: #alive element markup carries aria-valuemax="5"',
    aliveTagHM.includes('aria-valuemax="5"'), 'tag=' + aliveTagHM);
  check('hostiles: #alive element markup carries aria-valuenow="5"',
    aliveTagHM.includes('aria-valuenow="5"'), 'tag=' + aliveTagHM);
  check('hostiles: exactly one #alive element in the game source',
    (html.match(/id="alive"/g) || []).length === 1,
    'n=' + (html.match(/id="alive"/g) || []).length);
  check('hostiles: aliveEl binding line binds alive with killsEl (source pin)',
    html.includes("const aliveEl = document.getElementById('alive'), killsEl = document.getElementById('kills');"));
  check('hostiles: updateCombatHUD aliveEl textContent writer line is unchanged (source pin)',
    html.includes("aliveEl.textContent = enemies.filter(e => e.state !== 'dead').length;"));
  check('hostiles: updateCombatHUD syncs aliveEl ariaValueNow from the alive count exactly once (source pin)',
    (html.split("aliveEl.ariaValueNow = String(enemies.filter(e => e.state !== 'dead').length);").length - 1) === 1,
    'n=' + (html.split("aliveEl.ariaValueNow = String(enemies.filter(e => e.state !== 'dead').length);").length - 1));
  const savedStatesHM = G.enemies.map(e => e.state);
  const savedAliveHM = savedStatesHM.filter(s => s !== 'dead').length;
  G.enemies.forEach((e, i) => { e.state = i < 2 ? 'dead' : 'wander'; });
  G.updateCombatHUD();
  check('hostiles: runtime aliveEl text is 3 when two enemies are dead',
    String(G.aliveEl.textContent) === '3',
    'textContent=' + G.aliveEl.textContent);
  check('hostiles: runtime aliveEl ariaValueNow is 3 when two enemies are dead',
    String(G.aliveEl.ariaValueNow) === '3',
    'ariaValueNow=' + G.aliveEl.ariaValueNow);
  G.enemies.forEach((e, i) => { e.state = savedStatesHM[i]; });
  G.updateCombatHUD();
  check('hostiles: runtime aliveEl text is the saved alive count after restore',
    String(G.aliveEl.textContent) === String(savedAliveHM),
    'textContent=' + G.aliveEl.textContent + ' savedAlive=' + savedAliveHM);
  check('hostiles: runtime aliveEl ariaValueNow is the saved alive count after restore',
    String(G.aliveEl.ariaValueNow) === String(savedAliveHM),
    'ariaValueNow=' + G.aliveEl.ariaValueNow + ' savedAlive=' + savedAliveHM);
  check('hostiles: pins - 50 InstancedMesh literals unchanged', lineHasHM('new THREE.InstancedMesh') === 50,
    'n=' + lineHasHM('new THREE.InstancedMesh'));
  check('hostiles: pins - 92 Math.random lines unchanged', lineHasHM('Math.random') === 92,
    'n=' + lineHasHM('Math.random'));
  check('hostiles: pins - 72 setTimeout lines unchanged', lineHasHM('setTimeout') === 72,
    'n=' + lineHasHM('setTimeout'));
  check('hostiles: pins - no em dashes', !html.includes('\u2014'));
  check('hostiles: pins - no TODO markers', !/\bTODO\b/.test(html));
  check('hostiles: pins - allowed CDN URLs (Phase 1 set)',
    (() => { const u = [...new Set(html.match(/https?:\/\/[^"' )]+/g) || [])];
      return u.length >= 1 && u.every(x => ['https://unpkg.com/three@0.160.0/build/three.module.js', 'https://unpkg.com/three@0.160.0/examples/jsm/', 'https://unpkg.com/n8ao@2.0.1/dist/N8AO.js'].includes(x)); })());
  check('hostiles: the run leaves zero console errors/warnings',
    consoleProblems.length === probsHM, consoleProblems.slice(probsHM).join(' | '));
}

/* ================= BOAT SPEED METER v1 =================
   The boat speed readout is a real meter: role
   meter plus aria-label Boat speed and
   aria-valuemin 0 and aria-valuemax 43 in the
   #boatchip markup, with aria-valuenow kept in
   sync in boatUpdate beside the textContent
   writer. The sync uses the ariaValueNow IDL
   property, not setAttribute, because the
   headless stub elements have no setAttribute
   method. The displayed value is
   Math.round(Math.abs(speed) * 3.6): forward
   speed is capped at BOAT.topSpeed 12 with a
   wave penalty of at most 1, reverse is capped
   at 4, so the largest possible displayed
   value is Math.round(43.2) = 43 and the fixed
   valuemax 43 is exact. The runtime checks
   board a moored boat through the real entry
   path, set speed 5 with the HUD throttle
   forced open and run one frame with no keys
   held (coast decay only lowers 5 to about
   4.93, which still rounds to 18), then set
   speed 0, run one more frame, and exit,
   leaving the harness parked and clean. */
{
  const probsBS = consoleProblems.length;
  const linesBS = html.split('\n');
  const lineHasBS = sub => linesBS.filter(l => l.includes(sub)).length;
  check('boatspeed: BOAT SPEED METER v1 header is present exactly once in the game source',
    (html.split('BOAT SPEED METER v1').length - 1) === 1,
    'n=' + (html.split('BOAT SPEED METER v1').length - 1));
  const boatTagBS = (html.match(/<div id="boatchip"[^>]*>/) || [''])[0];
  check('boatspeed: #boatchip element markup carries role="meter"',
    boatTagBS.includes('role="meter"'), 'tag=' + boatTagBS);
  check('boatspeed: #boatchip element markup carries aria-label="Boat speed"',
    boatTagBS.includes('aria-label="Boat speed"'), 'tag=' + boatTagBS);
  check('boatspeed: #boatchip element markup carries aria-valuemin="0"',
    boatTagBS.includes('aria-valuemin="0"'), 'tag=' + boatTagBS);
  check('boatspeed: #boatchip element markup carries aria-valuemax="43"',
    boatTagBS.includes('aria-valuemax="43"'), 'tag=' + boatTagBS);
  check('boatspeed: #boatchip element markup carries aria-valuenow="0"',
    boatTagBS.includes('aria-valuenow="0"'), 'tag=' + boatTagBS);
  check('boatspeed: exactly one #boatchip element in the game source',
    (html.match(/id="boatchip"/g) || []).length === 1,
    'n=' + (html.match(/id="boatchip"/g) || []).length);
  check('boatspeed: boatChipEl binding line is unchanged (source pin)',
    html.includes("const boatChipEl = document.getElementById('boatchip');"));
  check('boatspeed: boatUpdate boatChipEl textContent writer line is unchanged (source pin)',
    html.includes("boatChipEl.textContent = 'BOAT - ' + Math.round(Math.abs(BOAT.speed) * 3.6) + ' KM/H';"));
  check('boatspeed: boatUpdate syncs boatChipEl ariaValueNow from the displayed speed exactly once (source pin)',
    (html.split('boatChipEl.ariaValueNow = String(Math.round(Math.abs(BOAT.speed) * 3.6));').length - 1) === 1,
    'n=' + (html.split('boatChipEl.ariaValueNow = String(Math.round(Math.abs(BOAT.speed) * 3.6));').length - 1));
  /* board a moored boat through the real entry path (boat block idiom) */
  G.P.dead = false; G.P.hp = 100; G.P.godT = 0; G.setHeat(0, true);
  for (const e of G.enemies) { e.live = false; e.state = 'wander'; e.hp = e.cfg.hp; e.group.position.set(500, 0, 500); }
  let dockChunkBS = null;
  for (let gx = -10; gx <= 10 && !dockChunkBS; gx++)
    for (let gz = -10; gz <= 10 && !dockChunkBS; gz++) {
      const d = G.dockFor(gx, gz);
      if (d) dockChunkBS = { gx, gz, d };
    }
  const dcxBS = (dockChunkBS.gx + 0.5) * 48, dczBS = (dockChunkBS.gz + 0.5) * 48;
  G.player.position.set(dcxBS, groundY(dcxBS, dczBS), dczBS);
  frame(3);
  const sBS = G.BOAT.slots.find(s => s.placed);
  G.player.position.set(sBS.x, 0.5, sBS.z);
  frame(2);
  G.boatEnter();
  G.keys.KeyW = false; G.keys.KeyA = false; G.keys.KeyS = false; G.keys.KeyD = false;
  G.keys.ArrowUp = false; G.keys.ArrowDown = false; G.keys.ArrowLeft = false; G.keys.ArrowRight = false;
  G.BOAT.speed = 5; G.BOAT.hudT = 1;
  frame(1);
  check('boatspeed: runtime boatChipEl text is BOAT - 18 KM/H at speed 5',
    G.boatChipEl.textContent === 'BOAT - 18 KM/H',
    'textContent=' + G.boatChipEl.textContent + ' speed=' + G.BOAT.speed);
  check('boatspeed: runtime boatChipEl ariaValueNow is 18 at speed 5',
    String(G.boatChipEl.ariaValueNow) === '18',
    'ariaValueNow=' + G.boatChipEl.ariaValueNow + ' speed=' + G.BOAT.speed);
  G.BOAT.speed = 0; G.BOAT.hudT = 1;
  frame(1);
  check('boatspeed: runtime boatChipEl text is BOAT - 0 KM/H at speed 0',
    G.boatChipEl.textContent === 'BOAT - 0 KM/H',
    'textContent=' + G.boatChipEl.textContent + ' speed=' + G.BOAT.speed);
  check('boatspeed: runtime boatChipEl ariaValueNow is 0 at speed 0',
    String(G.boatChipEl.ariaValueNow) === '0',
    'ariaValueNow=' + G.boatChipEl.ariaValueNow + ' speed=' + G.BOAT.speed);
  G.boatExit();
  check('boatspeed: chip is hidden after exit, boat parked at speed 0 and not driving',
    G.boatChipEl.style.display === 'none' && G.BOAT.driving === false && G.BOAT.speed === 0,
    'display=' + G.boatChipEl.style.display + ' driving=' + G.BOAT.driving + ' speed=' + G.BOAT.speed);
  check('boatspeed: pins - 50 InstancedMesh literals unchanged', lineHasBS('new THREE.InstancedMesh') === 50,
    'n=' + lineHasBS('new THREE.InstancedMesh'));
  check('boatspeed: pins - 92 Math.random lines unchanged', lineHasBS('Math.random') === 92,
    'n=' + lineHasBS('Math.random'));
  check('boatspeed: pins - 72 setTimeout lines unchanged', lineHasBS('setTimeout') === 72,
    'n=' + lineHasBS('setTimeout'));
  check('boatspeed: pins - no em dashes', !html.includes('\u2014'));
  check('boatspeed: pins - no TODO markers', !/\bTODO\b/.test(html));
  check('boatspeed: pins - allowed CDN URLs (Phase 1 set)',
    (() => { const u = [...new Set(html.match(/https?:\/\/[^"' )]+/g) || [])];
      return u.length >= 1 && u.every(x => ['https://unpkg.com/three@0.160.0/build/three.module.js', 'https://unpkg.com/three@0.160.0/examples/jsm/', 'https://unpkg.com/n8ao@2.0.1/dist/N8AO.js'].includes(x)); })());
  check('boatspeed: the run leaves zero console errors/warnings',
    consoleProblems.length === probsBS, consoleProblems.slice(probsBS).join(' | '));
}

/* ================= HELI SPEED METER v1 =================
   The helicopter speed readout is a real meter: the
   #helispd span nested in #helichip carries role
   meter plus aria-label Helicopter speed and
   aria-valuemin 0 and aria-valuemax 94 in markup,
   with aria-valuenow kept in sync in heliUpdate
   beside the textContent writers. The sync uses
   the ariaValueNow IDL property, not setAttribute,
   because the headless stub elements have no
   setAttribute method. The displayed value is
   Math.round(Math.abs(HELI.speed) * 3.6): forward
   speed is hard-capped at HELI.topSpeed 26, so the
   largest possible displayed value is
   Math.round(93.6) = 94 and the fixed valuemax 94
   is exact; reverse is capped at 6, well inside.
   Altitude has no clean absolute maximum (the 60u
   ceiling minus varying terrain), so it is NOT
   part of the meter value: #helialt stays plain
   text. The runtime checks board a parked
   helicopter through the real entry path (the heli
   block idiom), lift it 12m over the terrain at
   its boarding point, set speed 5 with the HUD
   throttle forced open and run one frame with no
   keys held (coast plus drag only lowers 5 to
   about 4.97, which still rounds to 18), then set
   speed 0, run one more frame, and exit, leaving
   the harness parked and clean. The altitude
   expectation is recomputed from the live position
   and terrain after the frame, because the frame
   integrates a fraction of a metre horizontally
   before the HUD write samples the ground. */
{
  const probsHS = consoleProblems.length;
  const linesHS = html.split('\n');
  const lineHasHS = sub => linesHS.filter(l => l.includes(sub)).length;
  check('helispd: HELI SPEED METER v1 header is present exactly once in the game source',
    (html.split('HELI SPEED METER v1').length - 1) === 1,
    'n=' + (html.split('HELI SPEED METER v1').length - 1));
  const heliTagHS = (html.match(/<span id="helispd"[^>]*>/) || [''])[0];
  check('helispd: #helispd element markup carries role="meter"',
    heliTagHS.includes('role="meter"'), 'tag=' + heliTagHS);
  check('helispd: #helispd element markup carries aria-label="Helicopter speed"',
    heliTagHS.includes('aria-label="Helicopter speed"'), 'tag=' + heliTagHS);
  check('helispd: #helispd element markup carries aria-valuemin="0"',
    heliTagHS.includes('aria-valuemin="0"'), 'tag=' + heliTagHS);
  check('helispd: #helispd element markup carries aria-valuemax="94"',
    heliTagHS.includes('aria-valuemax="94"'), 'tag=' + heliTagHS);
  check('helispd: #helispd element markup carries aria-valuenow="0"',
    heliTagHS.includes('aria-valuenow="0"'), 'tag=' + heliTagHS);
  check('helispd: #helichip markup nests #helispd meter and #helialt meter (source pin)',
    html.includes('<div id="helichip"><span id="helispd" role="meter" aria-label="Helicopter speed" aria-valuemin="0" aria-valuemax="94" aria-valuenow="0">HELI - 0 KM/H</span><span id="helialt" role="meter" aria-label="Helicopter altitude" aria-valuemin="0" aria-valuemax="63" aria-valuenow="0"> / ALT 0M</span></div>'));
  check('helispd: exactly one #helispd element in the game source',
    (html.match(/id="helispd"/g) || []).length === 1,
    'n=' + (html.match(/id="helispd"/g) || []).length);
  check('helispd: exactly one #helialt element in the game source',
    (html.match(/id="helialt"/g) || []).length === 1,
    'n=' + (html.match(/id="helialt"/g) || []).length);
  check('helispd: exactly one #helichip element in the game source',
    (html.match(/id="helichip"/g) || []).length === 1,
    'n=' + (html.match(/id="helichip"/g) || []).length);
  check('helispd: heliChipEl binding line is unchanged (source pin)',
    html.includes("const heliChipEl = document.getElementById('helichip');"));
  check('helispd: heliSpdEl binding line binds helispd (source pin)',
    html.includes("const heliSpdEl = document.getElementById('helispd');"));
  check('helispd: heliAltEl binding line binds helialt (source pin)',
    html.includes("const heliAltEl = document.getElementById('helialt');"));
  check('helispd: heliUpdate computes heliKmh from HELI.speed (source pin)',
    html.includes('const heliKmh = Math.round(Math.abs(HELI.speed) * 3.6);'));
  check('helispd: heliUpdate computes heliAltM from HELI.pos.y minus ground (source pin)',
    html.includes('const heliAltM = Math.max(0, Math.round(HELI.pos.y - ground));'));
  check('helispd: heliUpdate writes heliSpdEl textContent from heliKmh (source pin)',
    html.includes("heliSpdEl.textContent = 'HELI - ' + heliKmh + ' KM/H';"));
  check('helispd: heliUpdate writes heliAltEl textContent from heliAltM (source pin)',
    html.includes("heliAltEl.textContent = ' / ALT ' + heliAltM + 'M';"));
  check('helispd: heliUpdate syncs heliSpdEl ariaValueNow from heliKmh exactly once (source pin)',
    (html.split('heliSpdEl.ariaValueNow = String(heliKmh);').length - 1) === 1,
    'n=' + (html.split('heliSpdEl.ariaValueNow = String(heliKmh);').length - 1));
  check('helispd: the old heliChipEl textContent writer is gone (source pin)',
    !html.includes('heliChipEl.textContent'));
  /* board a parked helicopter through the real entry path (heli block idiom) */
  G.P.dead = false; G.P.hp = 100; G.P.godT = 0; G.setHeat(0, true);
  for (const e of G.enemies) { e.live = false; e.state = 'wander'; e.hp = e.cfg.hp; e.group.position.set(500, 0, 500); }
  let padChunkHS = null;
  for (let gx = -12; gx <= 12 && !padChunkHS; gx++)
    for (let gz = -12; gz <= 12 && !padChunkHS; gz++) {
      const d = G.helipadFor(gx, gz);
      if (d) padChunkHS = { gx, gz, d };
    }
  const hcxHS = (padChunkHS.gx + 0.5) * 48, hczHS = (padChunkHS.gz + 0.5) * 48;
  G.player.position.set(hcxHS, groundY(hcxHS, hczHS), hczHS);
  frame(3);
  const sHS = G.HELI.slots.find(s => s.placed);
  G.player.position.set(sHS.x, sHS.y + 1, sHS.z);
  frame(2);
  G.heliEnter();
  check('helispd: runtime boarded through heliEnter, chip is shown while flying',
    G.HELI.flying === true && G.heliChipEl.style.display === 'block',
    'flying=' + G.HELI.flying + ' display=' + G.heliChipEl.style.display);
  G.keys.KeyW = false; G.keys.KeyA = false; G.keys.KeyS = false; G.keys.KeyD = false;
  G.keys.ArrowUp = false; G.keys.ArrowDown = false; G.keys.ArrowLeft = false; G.keys.ArrowRight = false;
  G.keys.Space = false; G.keys.KeyC = false;
  G.HELI.pos.y = groundY(G.HELI.pos.x, G.HELI.pos.z) + 12;
  G.HELI.vy = 0; G.HELI.strafe = 0; G.HELI.grounded = false; G.HELI.tdT = 0;
  G.player.position.set(G.HELI.pos.x, G.HELI.pos.y, G.HELI.pos.z);
  G.HELI.speed = 5; G.HELI.hudT = 1;
  frame(1);
  check('helispd: runtime heliSpdEl text is HELI - 18 KM/H at speed 5',
    G.heliSpdEl.textContent === 'HELI - 18 KM/H',
    'textContent=' + G.heliSpdEl.textContent + ' speed=' + G.HELI.speed);
  check('helispd: runtime heliSpdEl ariaValueNow is 18 at speed 5',
    String(G.heliSpdEl.ariaValueNow) === '18',
    'ariaValueNow=' + G.heliSpdEl.ariaValueNow + ' speed=' + G.HELI.speed);
  const altHS5 = Math.max(0, Math.round(G.HELI.pos.y - G.terrainHeight(G.HELI.pos.x, G.HELI.pos.z)));
  check('helispd: runtime heliAltEl text is in sync with live altitude at speed 5',
    G.heliAltEl.textContent === ' / ALT ' + altHS5 + 'M' && Math.abs(altHS5 - 12) <= 1,
    'textContent=' + G.heliAltEl.textContent + ' expectedAlt=' + altHS5);
  check('helispd: runtime combined chip text keeps the HELI - n KM/H / ALT nM format',
    /^HELI - \d+ KM\/H \/ ALT \d+M$/.test(G.heliSpdEl.textContent + G.heliAltEl.textContent),
    G.heliSpdEl.textContent + G.heliAltEl.textContent);
  G.HELI.speed = 0; G.HELI.hudT = 1;
  frame(1);
  check('helispd: runtime heliSpdEl text is HELI - 0 KM/H at speed 0',
    G.heliSpdEl.textContent === 'HELI - 0 KM/H',
    'textContent=' + G.heliSpdEl.textContent + ' speed=' + G.HELI.speed);
  check('helispd: runtime heliSpdEl ariaValueNow is 0 at speed 0',
    String(G.heliSpdEl.ariaValueNow) === '0',
    'ariaValueNow=' + G.heliSpdEl.ariaValueNow + ' speed=' + G.HELI.speed);
  const altHS0 = Math.max(0, Math.round(G.HELI.pos.y - G.terrainHeight(G.HELI.pos.x, G.HELI.pos.z)));
  check('helispd: runtime heliAltEl text is in sync with live altitude at speed 0',
    G.heliAltEl.textContent === ' / ALT ' + altHS0 + 'M',
    'textContent=' + G.heliAltEl.textContent + ' expectedAlt=' + altHS0);
  G.heliExit();
  check('helispd: chip is hidden after exit and not flying',
    G.heliChipEl.style.display === 'none' && G.HELI.flying === false,
    'display=' + G.heliChipEl.style.display + ' flying=' + G.HELI.flying);
  check('helispd: pins - 50 InstancedMesh literals unchanged', lineHasHS('new THREE.InstancedMesh') === 50,
    'n=' + lineHasHS('new THREE.InstancedMesh'));
  check('helispd: pins - 92 Math.random lines unchanged', lineHasHS('Math.random') === 92,
    'n=' + lineHasHS('Math.random'));
  check('helispd: pins - 72 setTimeout lines unchanged', lineHasHS('setTimeout') === 72,
    'n=' + lineHasHS('setTimeout'));
  check('helispd: pins - no em dashes', !html.includes('\u2014'));
  check('helispd: pins - no TODO markers', !/\bTODO\b/.test(html));
  check('helispd: pins - allowed CDN URLs (Phase 1 set)',
    (() => { const u = [...new Set(html.match(/https?:\/\/[^"' )]+/g) || [])];
      return u.length >= 1 && u.every(x => ['https://unpkg.com/three@0.160.0/build/three.module.js', 'https://unpkg.com/three@0.160.0/examples/jsm/', 'https://unpkg.com/n8ao@2.0.1/dist/N8AO.js'].includes(x)); })());
  check('helispd: the run leaves zero console errors/warnings',
    consoleProblems.length === probsHS, consoleProblems.slice(probsHS).join(' | '));
}

/* ================= TRAIN SPEED METER v1 =================
   The train speed readout is a real meter: the
   #trainspd span nested in #trainchip carries role
   meter plus aria-label Train speed and
   aria-valuemin 0 and aria-valuemax 86 in markup,
   with aria-valuenow kept in sync in trainUpdate
   beside the textContent writers. The sync uses
   the ariaValueNow IDL property, not setAttribute,
   because the headless stub elements have no
   setAttribute method. The displayed value is
   Math.round(Math.abs(t.v) * 3.6) for the ridden
   train: t.v is hard-capped at TRAIN.cruise 24 by
   Math.min in trainSimOne (braking and dwell only
   lower it), so the largest possible displayed
   value is Math.round(86.4) = 86 and the fixed
   valuemax 86 is exact. The next-station name is
   not a number and has no bound, so it is NOT
   part of the meter value: #trainnext stays plain
   text. The runtime checks board train 0 through
   the real entry path (the train block idiom),
   pin its dwell so it cannot depart and read the
   stopped chip, then place it 400 units short of
   its next station at v 5 and run exactly one
   frame with the HUD throttle forced due: the
   sim raises v by accel 5 times one frame dt
   (about 0.08), which still rounds to 18, and the
   single frame guarantees a single HUD write
   before the 0.15s throttle can write again at a
   higher speed. A final dwell-pinned frame (the
   dwell branch of trainSimOne holds v at exactly
   0) reads 0 again before exit, which leaves the
   harness clean. */
{
  const probsTS = consoleProblems.length;
  const linesTS = html.split('\n');
  const lineHasTS = sub => linesTS.filter(l => l.includes(sub)).length;
  check('trainspd: TRAIN SPEED METER v1 header is present exactly once in the game source',
    (html.split('TRAIN SPEED METER v1').length - 1) === 1,
    'n=' + (html.split('TRAIN SPEED METER v1').length - 1));
  const trainTagTS = (html.match(/<span id="trainspd"[^>]*>/) || [''])[0];
  check('trainspd: #trainspd element markup carries role="meter"',
    trainTagTS.includes('role="meter"'), 'tag=' + trainTagTS);
  check('trainspd: #trainspd element markup carries aria-label="Train speed"',
    trainTagTS.includes('aria-label="Train speed"'), 'tag=' + trainTagTS);
  check('trainspd: #trainspd element markup carries aria-valuemin="0"',
    trainTagTS.includes('aria-valuemin="0"'), 'tag=' + trainTagTS);
  check('trainspd: #trainspd element markup carries aria-valuemax="86"',
    trainTagTS.includes('aria-valuemax="86"'), 'tag=' + trainTagTS);
  check('trainspd: #trainspd element markup carries aria-valuenow="0"',
    trainTagTS.includes('aria-valuenow="0"'), 'tag=' + trainTagTS);
  check('trainspd: #trainchip markup nests #trainspd meter and #trainnext plain text (source pin)',
    html.includes('<div id="trainchip"><span id="trainspd" role="meter" aria-label="Train speed" aria-valuemin="0" aria-valuemax="86" aria-valuenow="0">TRAIN - 0 KM/H</span><span id="trainnext"> / NEXT: RIVERSIDE</span></div>'));
  check('trainspd: exactly one #trainspd element in the game source',
    (html.match(/id="trainspd"/g) || []).length === 1,
    'n=' + (html.match(/id="trainspd"/g) || []).length);
  check('trainspd: exactly one #trainnext element in the game source',
    (html.match(/id="trainnext"/g) || []).length === 1,
    'n=' + (html.match(/id="trainnext"/g) || []).length);
  check('trainspd: exactly one #trainchip element in the game source',
    (html.match(/id="trainchip"/g) || []).length === 1,
    'n=' + (html.match(/id="trainchip"/g) || []).length);
  check('trainspd: trainChipEl binding line is unchanged (source pin)',
    html.includes("const trainChipEl = document.getElementById('trainchip');"));
  check('trainspd: trainSpdEl binding line binds trainspd (source pin)',
    html.includes("const trainSpdEl = document.getElementById('trainspd');"));
  check('trainspd: trainNextEl binding line binds trainnext (source pin)',
    html.includes("const trainNextEl = document.getElementById('trainnext');"));
  check('trainspd: trainUpdate computes trainKmh from the ridden train velocity (source pin)',
    html.includes('const trainKmh = Math.round(Math.abs(t.v) * 3.6);'));
  check('trainspd: trainUpdate writes trainSpdEl textContent from trainKmh (source pin)',
    html.includes("trainSpdEl.textContent = 'TRAIN - ' + trainKmh + ' KM/H';"));
  check('trainspd: trainUpdate writes trainNextEl textContent from trainStationName(nk) (source pin)',
    html.includes("trainNextEl.textContent = ' / NEXT: ' + trainStationName(nk);"));
  check('trainspd: trainUpdate syncs trainSpdEl ariaValueNow from trainKmh exactly once (source pin)',
    (html.split('trainSpdEl.ariaValueNow = String(trainKmh);').length - 1) === 1,
    'n=' + (html.split('trainSpdEl.ariaValueNow = String(trainKmh);').length - 1));
  check('trainspd: the old trainChipEl textContent writer is gone (source pin)',
    !html.includes('trainChipEl.textContent'));
  /* board train 0 through the real entry path (train block idiom) */
  const ttTS = G.TRAIN.trains[0];
  ttTS.dir = 1; ttTS.s = G.trainStationZ(0); ttTS.v = 0; ttTS.dwellT = 10; ttTS.nextK = 0; ttTS.braking = false;
  const bxTS = G.TRAIN_TRACK_X + 2, bzTS = ttTS.s;
  G.player.position.set(bxTS, groundY(bxTS, bzTS), bzTS);
  G.P.dead = false; G.P.hp = 100; G.P.godT = 0;
  frame(2);
  G.trainEnter();
  check('trainspd: runtime boarded through trainEnter, chip is shown while riding',
    G.TRAIN.riding === true && G.trainChipEl.style.display === 'block',
    'riding=' + G.TRAIN.riding + ' display=' + G.trainChipEl.style.display);
  ttTS.dwellT = 15;   // pinned at the platform: the train cannot depart during the stopped read
  frame(3);   // let the ride chip paint
  check('trainspd: runtime trainSpdEl text is TRAIN - 0 KM/H while dwelling',
    G.trainSpdEl.textContent === 'TRAIN - 0 KM/H',
    'textContent=' + G.trainSpdEl.textContent + ' v=' + ttTS.v);
  check('trainspd: runtime trainSpdEl ariaValueNow is 0 while dwelling',
    String(G.trainSpdEl.ariaValueNow) === '0',
    'ariaValueNow=' + G.trainSpdEl.ariaValueNow + ' v=' + ttTS.v);
  check('trainspd: runtime trainNextEl text names the next station while dwelling',
    G.trainNextEl.textContent === ' / NEXT: ' + G.trainStationName(G.trainNextK(ttTS.s, ttTS.dir)),
    'textContent=' + G.trainNextEl.textContent);
  check('trainspd: runtime combined chip text keeps the TRAIN - n KM/H / NEXT: name format',
    /^TRAIN - \d+ KM\/H \/ NEXT: [A-Z ]+$/.test(G.trainSpdEl.textContent + G.trainNextEl.textContent),
    G.trainSpdEl.textContent + G.trainNextEl.textContent);
  /* moving read: 400 units short of the next station, v 5, one forced HUD write */
  ttTS.dwellT = 0; ttTS.nextK = G.trainNextK(ttTS.s, ttTS.dir);
  ttTS.s = G.trainStationZ(ttTS.nextK) - 400; ttTS.v = 5; ttTS.braking = false;
  G.TRAIN.hudT = 0;
  frame(1);
  check('trainspd: runtime trainSpdEl text is TRAIN - 18 KM/H at speed 5',
    G.trainSpdEl.textContent === 'TRAIN - 18 KM/H',
    'textContent=' + G.trainSpdEl.textContent + ' v=' + ttTS.v);
  check('trainspd: runtime trainSpdEl ariaValueNow is 18 at speed 5',
    String(G.trainSpdEl.ariaValueNow) === '18',
    'ariaValueNow=' + G.trainSpdEl.ariaValueNow + ' v=' + ttTS.v);
  check('trainspd: runtime trainNextEl text names the next station at speed 5',
    /^ \/ NEXT: [A-Z ]+$/.test(G.trainNextEl.textContent),
    'textContent=' + G.trainNextEl.textContent);
  check('trainspd: runtime combined chip text keeps the TRAIN - n KM/H / NEXT: name format at speed 5',
    /^TRAIN - \d+ KM\/H \/ NEXT: [A-Z ]+$/.test(G.trainSpdEl.textContent + G.trainNextEl.textContent),
    G.trainSpdEl.textContent + G.trainNextEl.textContent);
  /* stopped read: dwell pins v at exactly 0, one forced HUD write */
  ttTS.dwellT = 15; ttTS.v = 0; G.TRAIN.hudT = 0;
  frame(1);
  check('trainspd: runtime trainSpdEl text is TRAIN - 0 KM/H at speed 0',
    G.trainSpdEl.textContent === 'TRAIN - 0 KM/H',
    'textContent=' + G.trainSpdEl.textContent + ' v=' + ttTS.v);
  check('trainspd: runtime trainSpdEl ariaValueNow is 0 at speed 0',
    String(G.trainSpdEl.ariaValueNow) === '0',
    'ariaValueNow=' + G.trainSpdEl.ariaValueNow + ' v=' + ttTS.v);
  G.trainExit();
  check('trainspd: chip is hidden after exit and not riding',
    G.trainChipEl.style.display === 'none' && G.TRAIN.riding === false,
    'display=' + G.trainChipEl.style.display + ' riding=' + G.TRAIN.riding);
  check('trainspd: pins - 50 InstancedMesh literals unchanged', lineHasTS('new THREE.InstancedMesh') === 50,
    'n=' + lineHasTS('new THREE.InstancedMesh'));
  check('trainspd: pins - 92 Math.random lines unchanged', lineHasTS('Math.random') === 92,
    'n=' + lineHasTS('Math.random'));
  check('trainspd: pins - 72 setTimeout lines unchanged', lineHasTS('setTimeout') === 72,
    'n=' + lineHasTS('setTimeout'));
  check('trainspd: pins - no em dashes', !html.includes('\u2014'));
  check('trainspd: pins - no TODO markers', !/\bTODO\b/.test(html));
  check('trainspd: pins - allowed CDN URLs (Phase 1 set)',
    (() => { const u = [...new Set(html.match(/https?:\/\/[^"' )]+/g) || [])];
      return u.length >= 1 && u.every(x => ['https://unpkg.com/three@0.160.0/build/three.module.js', 'https://unpkg.com/three@0.160.0/examples/jsm/', 'https://unpkg.com/n8ao@2.0.1/dist/N8AO.js'].includes(x)); })());
  check('trainspd: the run leaves zero console errors/warnings',
    consoleProblems.length === probsTS, consoleProblems.slice(probsTS).join(' | '));
}

/* ================= PLANE ALTITUDE METER v1 =================
   The plane altitude readout is a real meter: the
   #planealt span nested in #planechip carries role
   meter plus aria-label Plane altitude and
   aria-valuemin 0 and aria-valuemax 63 in markup,
   with aria-valuenow kept in sync in planeUpdate
   beside the textContent writers. The sync uses
   the ariaValueNow IDL property, not setAttribute,
   because the headless stub elements have no
   setAttribute method. The displayed value is
   Math.max(0, Math.round(PLANE.pos.y - ground))
   where ground is terrainHeight at the plane: the
   largest possible value is the PLANE.ceil 60 cap
   minus the terrainHeight floor -2.7 (amplitudes
   1.6+0.55+0.55), which is 62.7 and rounds up to
   the fixed valuemax 63. Speed is NOT part of the
   meter value: dive gains in planeUpdate can push
   PLANE.speed past PLANE.topSpeed, so #planespd
   stays plain text. The runtime checks board a
   parked airplane through the real entry path
   (the plane block idiom), force one HUD write on
   the ground at speed 0, then place the plane 30m
   over the terrain at its boarding point with
   speed 20 and the HUD throttle forced open and
   run one frame, and exit. Every altitude and
   speed expectation is recomputed from the live
   position, speed and terrain after the frame
   (the heli block idiom), because the frame
   integrates a fraction of a metre before the
   HUD write samples the ground, and the gear
   offset means the grounded altitude is the
   computed floor value rather than a hard 0. */
{
  const probsPA = consoleProblems.length;
  const linesPA = html.split('\n');
  const lineHasPA = sub => linesPA.filter(l => l.includes(sub)).length;
  check('planealt: PLANE ALTITUDE METER v1 header is present exactly once in the game source',
    (html.split('PLANE ALTITUDE METER v1').length - 1) === 1,
    'n=' + (html.split('PLANE ALTITUDE METER v1').length - 1));
  const planeTagPA = (html.match(/<span id="planealt"[^>]*>/) || [''])[0];
  check('planealt: #planealt element markup carries role="meter"',
    planeTagPA.includes('role="meter"'), 'tag=' + planeTagPA);
  check('planealt: #planealt element markup carries aria-label="Plane altitude"',
    planeTagPA.includes('aria-label="Plane altitude"'), 'tag=' + planeTagPA);
  check('planealt: #planealt element markup carries aria-valuemin="0"',
    planeTagPA.includes('aria-valuemin="0"'), 'tag=' + planeTagPA);
  check('planealt: #planealt element markup carries aria-valuemax="63"',
    planeTagPA.includes('aria-valuemax="63"'), 'tag=' + planeTagPA);
  check('planealt: #planealt element markup carries aria-valuenow="0"',
    planeTagPA.includes('aria-valuenow="0"'), 'tag=' + planeTagPA);
  check('planealt: #planechip markup nests #planespd plain text and #planealt meter (source pin)',
    html.includes('<div id="planechip"><span id="planespd">PLANE - 0 KM/H</span><span id="planealt" role="meter" aria-label="Plane altitude" aria-valuemin="0" aria-valuemax="63" aria-valuenow="0"> / ALT 0M</span></div>'));
  check('planealt: exactly one #planespd element in the game source',
    (html.match(/id="planespd"/g) || []).length === 1,
    'n=' + (html.match(/id="planespd"/g) || []).length);
  check('planealt: exactly one #planealt element in the game source',
    (html.match(/id="planealt"/g) || []).length === 1,
    'n=' + (html.match(/id="planealt"/g) || []).length);
  check('planealt: exactly one #planechip element in the game source',
    (html.match(/id="planechip"/g) || []).length === 1,
    'n=' + (html.match(/id="planechip"/g) || []).length);
  check('planealt: planeChipEl binding line is unchanged (source pin)',
    html.includes("const planeChipEl = document.getElementById('planechip');"));
  check('planealt: planeSpdEl binding line binds planespd (source pin)',
    html.includes("const planeSpdEl = document.getElementById('planespd');"));
  check('planealt: planeAltEl binding line binds planealt (source pin)',
    html.includes("const planeAltEl = document.getElementById('planealt');"));
  check('planealt: planeUpdate computes planeKmh from PLANE.speed (source pin)',
    html.includes('const planeKmh = Math.round(Math.abs(PLANE.speed) * 3.6);'));
  check('planealt: planeUpdate computes planeAltM from PLANE.pos.y minus ground (source pin)',
    html.includes('const planeAltM = Math.max(0, Math.round(PLANE.pos.y - ground));'));
  check('planealt: planeUpdate writes planeSpdEl textContent from planeKmh (source pin)',
    html.includes("planeSpdEl.textContent = 'PLANE - ' + planeKmh + ' KM/H';"));
  check('planealt: planeUpdate writes planeAltEl textContent from planeAltM (source pin)',
    html.includes("planeAltEl.textContent = ' / ALT ' + planeAltM + 'M';"));
  check('planealt: planeUpdate syncs planeAltEl ariaValueNow from planeAltM exactly once (source pin)',
    (html.split('planeAltEl.ariaValueNow = String(planeAltM);').length - 1) === 1,
    'n=' + (html.split('planeAltEl.ariaValueNow = String(planeAltM);').length - 1));
  check('planealt: the old planeChipEl textContent writer is gone (source pin)',
    !html.includes('planeChipEl.textContent'));
  /* board a parked airplane through the real entry path (plane block idiom) */
  G.P.dead = false; G.P.hp = 100; G.P.godT = 0; G.setHeat(0, true);
  for (const e of G.enemies) { e.live = false; e.state = 'wander'; e.hp = e.cfg.hp; e.group.position.set(500, 0, 500); }
  let stripChunkPA = null;
  for (let gx = -80; gx <= 80 && !stripChunkPA; gx++)
    for (let gz = -80; gz <= 80 && !stripChunkPA; gz++) {
      const d = G.airstripFor(gx, gz);
      if (d) stripChunkPA = { gx, gz, d };
    }
  check('planealt: test airstrip exists in the searched world',
    stripChunkPA !== null, 'stripChunk=' + stripChunkPA);
  const pcxPA = (stripChunkPA.gx + 0.5) * 48, pczPA = (stripChunkPA.gz + 0.5) * 48;
  G.player.position.set(pcxPA, groundY(pcxPA, pczPA), pczPA);
  frame(3);
  const sPA = G.PLANE.slots.find(s => s.placed);
  G.player.position.set(sPA.x, sPA.y + 1, sPA.z);
  frame(2);
  G.planeEnter();
  check('planealt: runtime boarded through planeEnter, chip is shown while flying',
    G.PLANE.flying === true && G.planeChipEl.style.display === 'block',
    'flying=' + G.PLANE.flying + ' display=' + G.planeChipEl.style.display);
  G.keys.KeyW = false; G.keys.KeyA = false; G.keys.KeyS = false; G.keys.KeyD = false;
  G.keys.ArrowUp = false; G.keys.ArrowDown = false; G.keys.ArrowLeft = false; G.keys.ArrowRight = false;
  G.keys.Space = false; G.keys.KeyC = false;
  /* grounded read: throttle and speed pinned at 0, one forced HUD write */
  G.PLANE.throttle = 0; G.PLANE.speed = 0; G.PLANE.hudT = 1;
  frame(1);
  const altPAG = Math.max(0, Math.round(G.PLANE.pos.y - G.terrainHeight(G.PLANE.pos.x, G.PLANE.pos.z)));
  check('planealt: runtime planeSpdEl text is PLANE - 0 KM/H on the ground',
    G.planeSpdEl.textContent === 'PLANE - 0 KM/H',
    'textContent=' + G.planeSpdEl.textContent + ' speed=' + G.PLANE.speed);
  check('planealt: runtime planeAltEl text is in sync with live grounded altitude',
    G.planeAltEl.textContent === ' / ALT ' + altPAG + 'M',
    'textContent=' + G.planeAltEl.textContent + ' expectedAlt=' + altPAG);
  check('planealt: runtime planeAltEl ariaValueNow matches the grounded altitude',
    String(G.planeAltEl.ariaValueNow) === String(altPAG),
    'ariaValueNow=' + G.planeAltEl.ariaValueNow + ' expectedAlt=' + altPAG);
  check('planealt: runtime combined chip text keeps the PLANE - 0 KM/H / ALT nM format on the ground',
    (G.planeSpdEl.textContent + G.planeAltEl.textContent) === 'PLANE - 0 KM/H / ALT ' + altPAG + 'M',
    G.planeSpdEl.textContent + G.planeAltEl.textContent);
  /* airborne read: 30m over the terrain, speed 20, one forced HUD write */
  G.PLANE.pos.y = G.terrainHeight(G.PLANE.pos.x, G.PLANE.pos.z) + 30;
  G.PLANE.vy = 0; G.PLANE.grounded = false; G.PLANE.crashT = 0; G.PLANE.landT = 0;
  G.PLANE.pitch = 0; G.PLANE.pitchVel = 0; G.PLANE.bank = 0; G.PLANE.autoLand = false;
  G.PLANE.speed = 20; G.PLANE.throttle = 0.75; G.PLANE.hudT = 1;
  frame(1);
  const altPAA = Math.max(0, Math.round(G.PLANE.pos.y - G.terrainHeight(G.PLANE.pos.x, G.PLANE.pos.z)));
  const kmhPAA = Math.round(Math.abs(G.PLANE.speed) * 3.6);
  check('planealt: runtime planeAltEl text is in sync with live altitude at 30m',
    G.planeAltEl.textContent === ' / ALT ' + altPAA + 'M',
    'textContent=' + G.planeAltEl.textContent + ' expectedAlt=' + altPAA);
  check('planealt: runtime altitude at 30m reads 30 within 1',
    Math.abs(altPAA - 30) <= 1, 'expectedAlt=' + altPAA);
  check('planealt: runtime planeAltEl ariaValueNow matches the altitude at 30m',
    String(G.planeAltEl.ariaValueNow) === String(altPAA),
    'ariaValueNow=' + G.planeAltEl.ariaValueNow + ' expectedAlt=' + altPAA);
  check('planealt: runtime planeSpdEl text is in sync with live speed at 30m',
    G.planeSpdEl.textContent === 'PLANE - ' + kmhPAA + ' KM/H',
    'textContent=' + G.planeSpdEl.textContent + ' expectedKmh=' + kmhPAA);
  check('planealt: runtime combined chip text keeps the PLANE - n KM/H / ALT nM format at 30m',
    /^PLANE - \d+ KM\/H \/ ALT \d+M$/.test(G.planeSpdEl.textContent + G.planeAltEl.textContent),
    G.planeSpdEl.textContent + G.planeAltEl.textContent);
  G.planeExit();
  check('planealt: chip is hidden after exit and not flying',
    G.planeChipEl.style.display === 'none' && G.PLANE.flying === false,
    'display=' + G.planeChipEl.style.display + ' flying=' + G.PLANE.flying);
  check('planealt: pins - 50 InstancedMesh literals unchanged', lineHasPA('new THREE.InstancedMesh') === 50,
    'n=' + lineHasPA('new THREE.InstancedMesh'));
  check('planealt: pins - 92 Math.random lines unchanged', lineHasPA('Math.random') === 92,
    'n=' + lineHasPA('Math.random'));
  check('planealt: pins - 72 setTimeout lines unchanged', lineHasPA('setTimeout') === 72,
    'n=' + lineHasPA('setTimeout'));
  check('planealt: pins - 2 THREE.Points objects unchanged', lineHasPA('new THREE.Points(') === 2,
    'n=' + lineHasPA('new THREE.Points('));
  check('planealt: pins - no em dashes', !html.includes('\u2014'));
  check('planealt: pins - no TODO markers', !/\bTODO\b/.test(html));
  check('planealt: pins - allowed CDN URLs (Phase 1 set)',
    (() => { const u = [...new Set(html.match(/https?:\/\/[^"' )]+/g) || [])];
      return u.length >= 1 && u.every(x => ['https://unpkg.com/three@0.160.0/build/three.module.js', 'https://unpkg.com/three@0.160.0/examples/jsm/', 'https://unpkg.com/n8ao@2.0.1/dist/N8AO.js'].includes(x)); })());
  check('planealt: the run leaves zero console errors/warnings',
    consoleProblems.length === probsPA, consoleProblems.slice(probsPA).join(' | '));
}

/* ================= HELI ALTITUDE METER v1 =================
   The helicopter altitude readout is a real meter: the
   #helialt span nested in #helichip carries role
   meter plus aria-label Helicopter altitude and
   aria-valuemin 0 and aria-valuemax 63 in markup,
   with aria-valuenow kept in sync in heliUpdate
   beside the textContent writers. The sync uses
   the ariaValueNow IDL property, not setAttribute,
   because the headless stub elements have no
   setAttribute method. The displayed value is
   Math.max(0, Math.round(HELI.pos.y - ground))
   where ground is terrainHeight at the helicopter:
   the largest possible value is the HELI.ceil 60
   cap minus the terrainHeight floor -2.7
   (amplitudes 1.6+0.55+0.55), which is 62.7 and
   rounds up to the fixed valuemax 63. Speed is NOT
   part of this meter value: it stays a separate
   meter on #helispd. The runtime checks board a
   parked helicopter through the real entry path
   (the helispd block idiom), lift it 12m over the
   terrain at its boarding point, set speed 5 with
   the HUD throttle forced open and run one frame
   with no keys held (coast plus drag only lowers 5
   to about 4.97, which still rounds to 18), then
   set speed 0, run one more frame, and exit,
   leaving the harness parked and clean. Every
   altitude expectation is recomputed from the live
   position and terrain after the frame, because
   the frame integrates a fraction of a metre
   horizontally before the HUD write samples the
   ground. */
{
  const probsHA = consoleProblems.length;
  const linesHA = html.split('\n');
  const lineHasHA = sub => linesHA.filter(l => l.includes(sub)).length;
  check('helialt: HELI ALTITUDE METER v1 header is present exactly once in the game source',
    (html.split('HELI ALTITUDE METER v1').length - 1) === 1,
    'n=' + (html.split('HELI ALTITUDE METER v1').length - 1));
  const heliTagHA = (html.match(/<span id="helialt"[^>]*>/) || [''])[0];
  check('helialt: #helialt element markup carries role="meter"',
    heliTagHA.includes('role="meter"'), 'tag=' + heliTagHA);
  check('helialt: #helialt element markup carries aria-label="Helicopter altitude"',
    heliTagHA.includes('aria-label="Helicopter altitude"'), 'tag=' + heliTagHA);
  check('helialt: #helialt element markup carries aria-valuemin="0"',
    heliTagHA.includes('aria-valuemin="0"'), 'tag=' + heliTagHA);
  check('helialt: #helialt element markup carries aria-valuemax="63"',
    heliTagHA.includes('aria-valuemax="63"'), 'tag=' + heliTagHA);
  check('helialt: #helialt element markup carries aria-valuenow="0"',
    heliTagHA.includes('aria-valuenow="0"'), 'tag=' + heliTagHA);
  check('helialt: #helichip markup nests #helispd meter and #helialt meter (source pin)',
    html.includes('<div id="helichip"><span id="helispd" role="meter" aria-label="Helicopter speed" aria-valuemin="0" aria-valuemax="94" aria-valuenow="0">HELI - 0 KM/H</span><span id="helialt" role="meter" aria-label="Helicopter altitude" aria-valuemin="0" aria-valuemax="63" aria-valuenow="0"> / ALT 0M</span></div>'));
  check('helialt: exactly one #helispd element in the game source',
    (html.match(/id="helispd"/g) || []).length === 1,
    'n=' + (html.match(/id="helispd"/g) || []).length);
  check('helialt: exactly one #helialt element in the game source',
    (html.match(/id="helialt"/g) || []).length === 1,
    'n=' + (html.match(/id="helialt"/g) || []).length);
  check('helialt: exactly one #helichip element in the game source',
    (html.match(/id="helichip"/g) || []).length === 1,
    'n=' + (html.match(/id="helichip"/g) || []).length);
  check('helialt: heliChipEl binding line is unchanged (source pin)',
    html.includes("const heliChipEl = document.getElementById('helichip');"));
  check('helialt: heliSpdEl binding line binds helispd (source pin)',
    html.includes("const heliSpdEl = document.getElementById('helispd');"));
  check('helialt: heliAltEl binding line binds helialt (source pin)',
    html.includes("const heliAltEl = document.getElementById('helialt');"));
  check('helialt: heliUpdate computes heliKmh from HELI.speed (source pin)',
    html.includes('const heliKmh = Math.round(Math.abs(HELI.speed) * 3.6);'));
  check('helialt: heliUpdate computes heliAltM from HELI.pos.y minus ground (source pin)',
    html.includes('const heliAltM = Math.max(0, Math.round(HELI.pos.y - ground));'));
  check('helialt: heliUpdate writes heliSpdEl textContent from heliKmh (source pin)',
    html.includes("heliSpdEl.textContent = 'HELI - ' + heliKmh + ' KM/H';"));
  check('helialt: heliUpdate writes heliAltEl textContent from heliAltM (source pin)',
    html.includes("heliAltEl.textContent = ' / ALT ' + heliAltM + 'M';"));
  check('helialt: heliUpdate syncs heliAltEl ariaValueNow from heliAltM exactly once (source pin)',
    (html.split('heliAltEl.ariaValueNow = String(heliAltM);').length - 1) === 1,
    'n=' + (html.split('heliAltEl.ariaValueNow = String(heliAltM);').length - 1));
  check('helialt: the old heliChipEl textContent writer is gone (source pin)',
    !html.includes('heliChipEl.textContent'));
  /* board a parked helicopter through the real entry path (helispd block idiom) */
  G.P.dead = false; G.P.hp = 100; G.P.godT = 0; G.setHeat(0, true);
  for (const e of G.enemies) { e.live = false; e.state = 'wander'; e.hp = e.cfg.hp; e.group.position.set(500, 0, 500); }
  let padChunkHA = null;
  for (let gx = -12; gx <= 12 && !padChunkHA; gx++)
    for (let gz = -12; gz <= 12 && !padChunkHA; gz++) {
      const d = G.helipadFor(gx, gz);
      if (d) padChunkHA = { gx, gz, d };
    }
  const hcxHA = (padChunkHA.gx + 0.5) * 48, hczHA = (padChunkHA.gz + 0.5) * 48;
  G.player.position.set(hcxHA, groundY(hcxHA, hczHA), hczHA);
  frame(3);
  const sHA = G.HELI.slots.find(s => s.placed);
  G.player.position.set(sHA.x, sHA.y + 1, sHA.z);
  frame(2);
  G.heliEnter();
  check('helialt: runtime boarded through heliEnter, chip is shown while flying',
    G.HELI.flying === true && G.heliChipEl.style.display === 'block',
    'flying=' + G.HELI.flying + ' display=' + G.heliChipEl.style.display);
  G.keys.KeyW = false; G.keys.KeyA = false; G.keys.KeyS = false; G.keys.KeyD = false;
  G.keys.ArrowUp = false; G.keys.ArrowDown = false; G.keys.ArrowLeft = false; G.keys.ArrowRight = false;
  G.keys.Space = false; G.keys.KeyC = false;
  G.HELI.pos.y = groundY(G.HELI.pos.x, G.HELI.pos.z) + 12;
  G.HELI.vy = 0; G.HELI.strafe = 0; G.HELI.grounded = false; G.HELI.tdT = 0;
  G.player.position.set(G.HELI.pos.x, G.HELI.pos.y, G.HELI.pos.z);
  G.HELI.speed = 5; G.HELI.hudT = 1;
  frame(1);
  const altHA5 = Math.max(0, Math.round(G.HELI.pos.y - G.terrainHeight(G.HELI.pos.x, G.HELI.pos.z)));
  check('helialt: runtime heliAltEl text is in sync with live altitude at 12m',
    G.heliAltEl.textContent === ' / ALT ' + altHA5 + 'M' && Math.abs(altHA5 - 12) <= 1,
    'textContent=' + G.heliAltEl.textContent + ' expectedAlt=' + altHA5);
  check('helialt: runtime heliAltEl ariaValueNow matches the altitude at 12m',
    String(G.heliAltEl.ariaValueNow) === String(altHA5),
    'ariaValueNow=' + G.heliAltEl.ariaValueNow + ' expectedAlt=' + altHA5);
  check('helialt: runtime heliSpdEl text is HELI - 18 KM/H at speed 5',
    G.heliSpdEl.textContent === 'HELI - 18 KM/H',
    'textContent=' + G.heliSpdEl.textContent + ' speed=' + G.HELI.speed);
  check('helialt: runtime combined chip text keeps the HELI - n KM/H / ALT nM format',
    /^HELI - \d+ KM\/H \/ ALT \d+M$/.test(G.heliSpdEl.textContent + G.heliAltEl.textContent),
    G.heliSpdEl.textContent + G.heliAltEl.textContent);
  G.HELI.speed = 0; G.HELI.hudT = 1;
  frame(1);
  const altHA0 = Math.max(0, Math.round(G.HELI.pos.y - G.terrainHeight(G.HELI.pos.x, G.HELI.pos.z)));
  check('helialt: runtime heliAltEl text is in sync with live altitude at speed 0',
    G.heliAltEl.textContent === ' / ALT ' + altHA0 + 'M',
    'textContent=' + G.heliAltEl.textContent + ' expectedAlt=' + altHA0);
  check('helialt: runtime heliAltEl ariaValueNow matches the altitude at speed 0',
    String(G.heliAltEl.ariaValueNow) === String(altHA0),
    'ariaValueNow=' + G.heliAltEl.ariaValueNow + ' expectedAlt=' + altHA0);
  G.heliExit();
  check('helialt: chip is hidden after exit and not flying',
    G.heliChipEl.style.display === 'none' && G.HELI.flying === false,
    'display=' + G.heliChipEl.style.display + ' flying=' + G.HELI.flying);
  check('helialt: pins - 50 InstancedMesh literals unchanged', lineHasHA('new THREE.InstancedMesh') === 50,
    'n=' + lineHasHA('new THREE.InstancedMesh'));
  check('helialt: pins - 92 Math.random lines unchanged', lineHasHA('Math.random') === 92,
    'n=' + lineHasHA('Math.random'));
  check('helialt: pins - 72 setTimeout lines unchanged', lineHasHA('setTimeout') === 72,
    'n=' + lineHasHA('setTimeout'));
  check('helialt: pins - 2 THREE.Points objects unchanged', lineHasHA('new THREE.Points(') === 2,
    'n=' + lineHasHA('new THREE.Points('));
  check('helialt: pins - no em dashes', !html.includes('\u2014'));
  check('helialt: pins - no TODO markers', !/\bTODO\b/.test(html));
  check('helialt: pins - allowed CDN URLs (Phase 1 set)',
    (() => { const u = [...new Set(html.match(/https?:\/\/[^"' )]+/g) || [])];
      return u.length >= 1 && u.every(x => ['https://unpkg.com/three@0.160.0/build/three.module.js', 'https://unpkg.com/three@0.160.0/examples/jsm/', 'https://unpkg.com/n8ao@2.0.1/dist/N8AO.js'].includes(x)); })());
  check('helialt: the run leaves zero console errors/warnings',
    consoleProblems.length === probsHA, consoleProblems.slice(probsHA).join(' | '));
}

