/* ================= GROUND SPEED METER v1 =================
   The shared ground speed readout is a real meter: the
   #spdnum span inside #speedo carries role meter plus
   aria-label Ground speed and aria-valuemin 0 and
   aria-valuemax 144 in markup, and every one of the 8
   writer sites (car, horse, bus aboard, taxi riding,
   fire truck, motorcycle, bicycle, scooter) syncs
   valuenow right after its textContent write via the
   ariaValueNow property (stub-safe idiom, no
   setAttribute). The bound is provable: every mode
   clamps or approaches its cap and the fleet max is
   the motorcycle boost cap of 40 units per second, so
   the displayed KM/H stays within 0..144. The visible
   text is unchanged: the numeric span still sits in
   front of the literal KM/H suffix. The stub stores
   the numeric textContent assignment uncoerced (a real
   browser coerces it to a string), so the runtime text
   checks below compare through String(). The runtime
   drive runs the real car path through the real tick:
   driving state, CAR.speed 10, forced CAR.hudT, one
   frame, then the expected value is recomputed from
   the live CAR.speed after the frame. */
{
  const probsSM = consoleProblems.length;
  const linesSM = html.split('\n');
  const lineHasSM = sub => linesSM.filter(l => l.includes(sub)).length;
  check('spdmeter: GROUND SPEED METER v1 header is present exactly once in the game source',
    (html.split('GROUND SPEED METER v1').length - 1) === 1,
    'n=' + (html.split('GROUND SPEED METER v1').length - 1));
  check('spdmeter: #spdnum full tag matches exactly (source pin)',
    html.includes('<span id="spdnum" role="meter" aria-label="Ground speed" aria-valuemin="0" aria-valuemax="144" aria-valuenow="0">0</span>'));
  check('spdmeter: exactly one #spdnum element in the game source',
    (html.match(/id="spdnum"/g) || []).length === 1,
    'n=' + (html.match(/id="spdnum"/g) || []).length);
  check('spdmeter: spdNumEl binding line binds spdnum (source pin)',
    html.includes("const spdNumEl = document.getElementById('spdnum');"));
  check('spdmeter: car writer textContent line is unchanged (source pin)',
    html.includes('    spdNumEl.textContent = Math.round(Math.abs(CAR.speed) * 3.6);'));
  check('spdmeter: car writer syncs ariaValueNow with the identical expression (source pin)',
    html.includes('    spdNumEl.ariaValueNow = String(Math.round(Math.abs(CAR.speed) * 3.6));'));
  check('spdmeter: horse writer textContent line is unchanged (source pin)',
    html.includes('    spdNumEl.textContent = Math.round(HORSE.speed * 3.6);'));
  check('spdmeter: horse writer syncs ariaValueNow with the identical expression (source pin)',
    html.includes('    spdNumEl.ariaValueNow = String(Math.round(HORSE.speed * 3.6));'));
  check('spdmeter: bus writer textContent line is unchanged (source pin)',
    html.includes('    if (aboard) spdNumEl.textContent = Math.round(Math.abs(BUS.speed) * 3.6);'));
  check('spdmeter: bus writer syncs ariaValueNow gated by aboard, identical expression (source pin)',
    html.includes('    if (aboard) spdNumEl.ariaValueNow = String(Math.round(Math.abs(BUS.speed) * 3.6));'));
  check('spdmeter: taxi writer textContent line is unchanged (source pin)',
    html.includes('    if (TX.riding) spdNumEl.textContent = Math.round(Math.abs(TX.speed) * 3.6);'));
  check('spdmeter: taxi writer syncs ariaValueNow gated by riding, identical expression (source pin)',
    html.includes('    if (TX.riding) spdNumEl.ariaValueNow = String(Math.round(Math.abs(TX.speed) * 3.6));'));
  check('spdmeter: fire truck writer textContent line is unchanged (source pin)',
    html.includes('  spdNumEl.textContent = Math.round(Math.abs(FT.speed) * 3.6);'));
  check('spdmeter: fire truck writer syncs ariaValueNow with the identical expression (source pin)',
    html.includes('  spdNumEl.ariaValueNow = String(Math.round(Math.abs(FT.speed) * 3.6));'));
  check('spdmeter: motorcycle writer textContent line is unchanged (source pin)',
    html.includes('    spdNumEl.textContent = Math.round(Math.abs(BIKE.speed) * 3.6);'));
  check('spdmeter: motorcycle writer syncs ariaValueNow with the identical expression (source pin)',
    html.includes('    spdNumEl.ariaValueNow = String(Math.round(Math.abs(BIKE.speed) * 3.6));'));
  check('spdmeter: bicycle writer textContent line is unchanged (source pin)',
    html.includes('    spdNumEl.textContent = Math.round(Math.abs(BC.speed) * 3.6);'));
  check('spdmeter: bicycle writer syncs ariaValueNow with the identical expression (source pin)',
    html.includes('    spdNumEl.ariaValueNow = String(Math.round(Math.abs(BC.speed) * 3.6));'));
  check('spdmeter: scooter writer textContent line is unchanged (source pin)',
    html.includes('    spdNumEl.textContent = Math.round(SC.speed * 3.6);'));
  check('spdmeter: scooter writer syncs ariaValueNow with the identical expression (source pin)',
    html.includes('    spdNumEl.ariaValueNow = String(Math.round(SC.speed * 3.6));'));
  check('spdmeter: exactly 8 ariaValueNow sync sites in the game source (count pin)',
    (html.split('spdNumEl.ariaValueNow = String(').length - 1) === 8,
    'n=' + (html.split('spdNumEl.ariaValueNow = String(').length - 1));
  /* runtime: boot state, then a real car drive through the real tick */
  check('spdmeter: runtime spdNumEl exists',
    !!G.spdNumEl);
  check('spdmeter: runtime spdNumEl text is 0 at boot',
    String(G.spdNumEl.textContent) === '0',
    'textContent=' + G.spdNumEl.textContent);
  check('spdmeter: runtime spdNumEl ariaValueNow is 0 at boot',
    G.spdNumEl.ariaValueNow === '0',
    'ariaValueNow=' + G.spdNumEl.ariaValueNow);
  const saveSM = {
    driving: G.CAR.driving, speed: G.CAR.speed, hudT: G.CAR.hudT,
    steer: G.CAR.steer, slip: G.CAR.slip, charge: G.CAR.charge, drifting: G.CAR.drifting,
    hp: G.CAR.hp, dead: G.P.dead,
    px: G.player.position.x, py: G.player.position.y, pz: G.player.position.z,
    vis: G.player.visible,
    kw: G.keys.KeyW, ks: G.keys.KeyS, ka: G.keys.KeyA, kd: G.keys.KeyD, ksp: G.keys.Space,
  };
  const carPosSM = G.CAR.pos.clone();
  G.P.dead = false;
  G.keys.KeyW = false; G.keys.KeyS = false; G.keys.KeyA = false; G.keys.KeyD = false; G.keys.Space = false;
  G.CAR.driving = true; G.player.visible = false;
  G.CAR.speed = 10; G.CAR.hudT = 1;
  frame(1);
  const expSM = String(Math.round(Math.abs(G.CAR.speed) * 3.6));
  check('spdmeter: runtime spdNumEl text matches the live CAR.speed after one tick at speed 10',
    String(G.spdNumEl.textContent) === expSM,
    'textContent=' + G.spdNumEl.textContent + ' expected=' + expSM + ' carSpeed=' + G.CAR.speed);
  check('spdmeter: runtime spdNumEl ariaValueNow matches the live CAR.speed after one tick at speed 10',
    G.spdNumEl.ariaValueNow === expSM,
    'ariaValueNow=' + G.spdNumEl.ariaValueNow + ' expected=' + expSM + ' carSpeed=' + G.CAR.speed);
  check('spdmeter: runtime driven value is above 0 and within the 0..144 bound',
    Number(G.spdNumEl.ariaValueNow) > 0 && Number(G.spdNumEl.ariaValueNow) <= 144,
    'ariaValueNow=' + G.spdNumEl.ariaValueNow);
  G.CAR.speed = 0; G.CAR.hudT = 1;
  frame(1);
  check('spdmeter: runtime spdNumEl text returns to 0 after one tick at speed 0',
    String(G.spdNumEl.textContent) === '0',
    'textContent=' + G.spdNumEl.textContent);
  check('spdmeter: runtime spdNumEl ariaValueNow returns to 0 after one tick at speed 0',
    G.spdNumEl.ariaValueNow === '0',
    'ariaValueNow=' + G.spdNumEl.ariaValueNow);
  if (G.CAR.driving) G.carExit();
  G.CAR.driving = saveSM.driving; G.CAR.speed = saveSM.speed; G.CAR.hudT = saveSM.hudT;
  G.CAR.steer = saveSM.steer; G.CAR.slip = saveSM.slip; G.CAR.charge = saveSM.charge;
  G.CAR.drifting = saveSM.drifting; G.CAR.hp = saveSM.hp;
  G.CAR.pos.copy(carPosSM);
  G.P.dead = saveSM.dead;
  G.player.position.set(saveSM.px, saveSM.py, saveSM.pz);
  G.player.visible = saveSM.vis;
  G.keys.KeyW = saveSM.kw; G.keys.KeyS = saveSM.ks; G.keys.KeyA = saveSM.ka; G.keys.KeyD = saveSM.kd; G.keys.Space = saveSM.ksp;
  check('spdmeter: cleanup leaves the car parked and the player visible',
    G.CAR.driving === false && G.player.visible === true,
    'driving=' + G.CAR.driving + ' visible=' + G.player.visible);
  check('spdmeter: pins - 50 InstancedMesh literals unchanged', lineHasSM('new THREE.InstancedMesh') === 50,
    'n=' + lineHasSM('new THREE.InstancedMesh'));
  check('spdmeter: pins - 92 Math.random lines unchanged', lineHasSM('Math.random') === 92,
    'n=' + lineHasSM('Math.random'));
  check('spdmeter: pins - 72 setTimeout lines unchanged', lineHasSM('setTimeout') === 72,
    'n=' + lineHasSM('setTimeout'));
  check('spdmeter: pins - 2 THREE.Points objects unchanged', lineHasSM('new THREE.Points(') === 2,
    'n=' + lineHasSM('new THREE.Points('));
  check('spdmeter: pins - no em dashes', !html.includes('\u2014'));
  check('spdmeter: pins - no TODO markers', !/\bTODO\b/.test(html));
  check('spdmeter: pins - allowed CDN URLs (Phase 1 set)',
    (() => { const u = [...new Set(html.match(/https?:\/\/[^\"' )]+/g) || [])];
      return u.length >= 1 && u.every(x => ['https://unpkg.com/three@0.160.0/build/three.module.js', 'https://unpkg.com/three@0.160.0/examples/jsm/', 'https://unpkg.com/n8ao@2.0.1/dist/N8AO.js'].includes(x)); })());
  check('spdmeter: the run leaves zero console errors/warnings',
    consoleProblems.length === probsSM, consoleProblems.slice(probsSM).join(' | '));
}

/* ================= REDUCED MOTION v7 =================
   The storm lightning flash now follows the same
   P.traumaOn gate as v1-v5. When the gate is off, the
   computed intensity is zeroed inside updateBolt before
   the writer lines, so the bolt light stays dark and
   the #boltflash DOM layer stays at opacity 0. The pulse
   timeline, storm state, rain, delayed thunder, and the
   wildfire strike in triggerBolt are unchanged, and
   no-preference users see the identical flash. */
{
  const probsRB = consoleProblems.length;
  const linesRB = html.split('\n');
  const lineHasRB = sub => linesRB.filter(l => l.includes(sub)).length;
  check('rmbolt: REDUCED MOTION v7 header is present exactly once in the game source',
    (html.split('/* REDUCED MOTION v7').length - 1) === 1,
    'n=' + (html.split('/* REDUCED MOTION v7').length - 1));
  check('rmbolt: exact gate line if (!P.traumaOn) I = 0; is present exactly once in the game source',
    (html.split('if (!P.traumaOn) I = 0;').length - 1) === 1,
    'n=' + (html.split('if (!P.traumaOn) I = 0;').length - 1));
  const boltIdxRB = html.indexOf('function updateBolt(dt) {');
  const boltSliceRB = boltIdxRB >= 0 ? html.slice(boltIdxRB, boltIdxRB + 700) : '';
  check('rmbolt: updateBolt still contains the writer line bolt.intensity = I;',
    boltSliceRB.includes('bolt.intensity = I;'),
    'slice=' + boltSliceRB.slice(0, 120));
  check('rmbolt: updateBolt still contains the boltFlashEl opacity writer line',
    boltSliceRB.includes('boltFlashEl.style.opacity = Math.min(0.15, I * 0.035);'),
    'slice=' + boltSliceRB.slice(0, 120));
  check('rmbolt: runtime exposures exist (bolt, triggerBolt, updateBolt, boltFlashEl)',
    !!G.bolt && typeof G.triggerBolt === 'function' && typeof G.updateBolt === 'function' && !!G.boltFlashEl);
  check('rmbolt-pins: 50 InstancedMesh literals unchanged', lineHasRB('new THREE.InstancedMesh') === 50,
    'n=' + lineHasRB('new THREE.InstancedMesh'));
  check('rmbolt-pins: 92 Math.random lines unchanged', lineHasRB('Math.random') === 92,
    'n=' + lineHasRB('Math.random'));
  check('rmbolt-pins: 72 setTimeout lines unchanged', lineHasRB('setTimeout') === 72,
    'n=' + lineHasRB('setTimeout'));
  check('rmbolt-pins: 2 THREE.Points objects unchanged', lineHasRB('new THREE.Points(') === 2,
    'n=' + lineHasRB('new THREE.Points('));
  check('rmbolt-pins: no em dashes', !html.includes('\u2014'));
  check('rmbolt-pins: no TODO markers', !/\bTODO\b/.test(html));
  /* runtime, gate ON: rain state keeps triggerBolt off the wildfire path */
  const saveStateRB = G.WX.state;
  G.WX.state = 'rain';
  if (!G.P.traumaOn) G.toggleTrauma();
  G.triggerBolt();
  let sawFlashRB = false;
  for (let i = 0; i < 60 && G.WX.boltT !== -1; i++) {
    G.updateBolt(0.016);
    if (G.bolt.intensity > 0 || Number(G.boltFlashEl.style.opacity) > 0) sawFlashRB = true;
  }
  check('rmbolt: gate ON flash exceeds 0 at some step (bolt intensity or flash opacity)',
    sawFlashRB, 'intensity=' + G.bolt.intensity + ' opacity=' + G.boltFlashEl.style.opacity);
  let drainRB = 0;
  while (G.WX.boltT !== -1 && drainRB < 200) { G.updateBolt(0.016); drainRB++; }
  check('rmbolt: gate ON outputs are both 0 after the pulse window expires',
    G.WX.boltT === -1 && G.bolt.intensity === 0 && Number(G.boltFlashEl.style.opacity) === 0,
    'boltT=' + G.WX.boltT + ' intensity=' + G.bolt.intensity + ' opacity=' + G.boltFlashEl.style.opacity);
  /* runtime, gate OFF: every step in the whole pulse window stays dark */
  G.P.traumaOn = false;
  G.triggerBolt();
  let allZeroRB = true;
  let stepsRB = 0;
  while (G.WX.boltT !== -1 && stepsRB < 200) {
    G.updateBolt(0.016);
    stepsRB++;
    if (G.bolt.intensity !== 0 || Number(G.boltFlashEl.style.opacity) !== 0) allZeroRB = false;
  }
  check('rmbolt: gate OFF bolt intensity and flash opacity are 0 at every step',
    allZeroRB, 'steps=' + stepsRB + ' intensity=' + G.bolt.intensity + ' opacity=' + G.boltFlashEl.style.opacity);
  check('rmbolt: gate OFF pulse window ran to completion (boltT back to -1)',
    stepsRB > 0 && G.WX.boltT === -1,
    'steps=' + stepsRB + ' boltT=' + G.WX.boltT);
  /* cleanup */
  if (!G.P.traumaOn) G.toggleTrauma();
  G.WX.state = saveStateRB;
  G.WX.boltT = -1;
  G.bolt.intensity = 0;
  G.boltFlashEl.style.opacity = 0;
  check('rmbolt: cleanup restores traumaOn true, WX.state, boltT -1, and zeroed outputs',
    G.P.traumaOn === true && G.WX.state === saveStateRB && G.WX.boltT === -1
    && G.bolt.intensity === 0 && Number(G.boltFlashEl.style.opacity) === 0,
    'on=' + G.P.traumaOn + ' state=' + G.WX.state + ' boltT=' + G.WX.boltT);
  check('rmbolt: the run leaves zero console errors/warnings',
    consoleProblems.length === probsRB, consoleProblems.slice(probsRB).join(' | '));
}

/* REDUCED MOTION v8: the two JavaScript-driven HUD flashes (the loyalty
   chip glow in loyalTick and the slot win color flash in slotUpdate)
   follow the P.traumaOn gate as v1-v5 and v7. When the gate is off, each
   holds its static form for the same window, then clears exactly as
   before, and no-preference users see the identical toggles. */
{
  const probsHF = consoleProblems.length;
  const linesHF = html.split('\n');
  const lineHasHF = sub => linesHF.filter(l => l.includes(sub)).length;
  check('rmhudflash: REDUCED MOTION v8 header is present exactly once in the game source',
    (html.split('/* REDUCED MOTION v8: the JavaScript-driven HUD flashes').length - 1) === 1,
    'n=' + (html.split('/* REDUCED MOTION v8: the JavaScript-driven HUD flashes').length - 1));
  check('rmhudflash: REDUCED MOTION v8 is mentioned exactly 5 times (header x2, both gate lines, slot cross-reference)',
    (html.split('REDUCED MOTION v8').length - 1) === 5,
    'n=' + (html.split('REDUCED MOTION v8').length - 1));
  check('rmhudflash: loyal gate line is present exactly once in the game source',
    (html.split("loyalChipEl.style.boxShadow = !P.traumaOn ? '0 0 12px #ffd24a' :").length - 1) === 1,
    'n=' + (html.split("loyalChipEl.style.boxShadow = !P.traumaOn ? '0 0 12px #ffd24a' :").length - 1));
  check('rmhudflash: slot gate line is present exactly once in the game source',
    (html.split("slotWinEl.style.color = !P.traumaOn ? '#ffd24a' :").length - 1) === 1,
    'n=' + (html.split("slotWinEl.style.color = !P.traumaOn ? '#ffd24a' :").length - 1));
  check('rmhudflash: loyal expiry clear line is unchanged',
    html.includes("if (LOYAL.flashT <= 0) loyalChipEl.style.boxShadow = 'none';"));
  check('rmhudflash: slot expiry reset line is unchanged',
    html.includes("if (SLOT.winFlashT <= 0) slotWinEl.style.color = '#cfe8d8';"));
  check('rmhudflash: runtime exposures exist (LOYAL, loyalTick, loyalChipEl, SLOT, slotUpdate, slotWinEl)',
    !!G.LOYAL && typeof G.loyalTick === 'function' && !!G.loyalChipEl
    && !!G.SLOT && typeof G.slotUpdate === 'function' && !!G.slotWinEl);
  check('rmhudflash-pins: 50 InstancedMesh literals unchanged', lineHasHF('new THREE.InstancedMesh') === 50,
    'n=' + lineHasHF('new THREE.InstancedMesh'));
  check('rmhudflash-pins: 92 Math.random lines unchanged', lineHasHF('Math.random') === 92,
    'n=' + lineHasHF('Math.random'));
  check('rmhudflash-pins: 72 setTimeout lines unchanged', lineHasHF('setTimeout') === 72,
    'n=' + lineHasHF('setTimeout'));
  check('rmhudflash-pins: 2 THREE.Points objects unchanged', lineHasHF('new THREE.Points(') === 2,
    'n=' + lineHasHF('new THREE.Points('));
  check('rmhudflash-pins: no em dashes', !html.includes('\u2014'));
  check('rmhudflash-pins: no TODO markers', !/\bTODO\b/.test(html));
  /* save harness state the drives touch */
  const saveTraumaHF = G.P.traumaOn, saveDeadHF = G.P.dead;
  const savePlayingHF = G.SLOT.playing, saveSpinningHF = G.SLOT.spinning;
  const savePosHF = { x: G.player.position.x, y: G.player.position.y, z: G.player.position.z, ry: G.player.rotation.y };
  const GLOW = '0 0 12px #ffd24a', GOLD = '#ffd24a', WHITE = '#ffffff', RESET = '#cfe8d8';
  function driveSlotHF() {
    const colors = [];
    G.SLOT.playing = true; G.SLOT.spinning = false; G.P.dead = false;
    G.SLOT.winFlashT = 1.6;
    let guard = 0;
    while (G.SLOT.winFlashT > 0 && guard < 200) { G.slotUpdate(0.05, 0); colors.push(G.slotWinEl.style.color); guard++; }
    return colors;
  }
  function driveLoyalHF() {
    const shadows = [];
    G.LOYAL.flashT = 1.2; G.LOYAL.stingQ.length = 0;
    let guard = 0;
    while (G.LOYAL.flashT > 0 && guard < 200) { G.loyalTick(0.05); shadows.push(G.loyalChipEl.style.boxShadow); guard++; }
    return shadows;
  }
  /* runtime, gate ON: both flashes toggle, then clear on expiry */
  G.P.traumaOn = true;
  const slotOnHF = driveSlotHF();
  check('rmhudflash: gate ON slot win flash toggles gold and white across the window',
    slotOnHF.includes(GOLD) && slotOnHF.includes(WHITE),
    'colors=' + [...new Set(slotOnHF)].join(','));
  check('rmhudflash: gate ON slot win flash ends on the reset color with the timer drained',
    slotOnHF[slotOnHF.length - 1] === RESET && G.SLOT.winFlashT <= 0,
    'last=' + slotOnHF[slotOnHF.length - 1] + ' winFlashT=' + G.SLOT.winFlashT);
  const loyalOnHF = driveLoyalHF();
  check('rmhudflash: gate ON loyalty flash toggles glow and none across the window',
    loyalOnHF.includes(GLOW) && loyalOnHF.includes('none'),
    'shadows=' + [...new Set(loyalOnHF)].join(' | '));
  check('rmhudflash: gate ON loyalty flash timer drains to expiry',
    G.LOYAL.flashT <= 0, 'flashT=' + G.LOYAL.flashT);
  /* runtime, gate OFF: static forms hold every step, expiry clear unchanged */
  G.P.traumaOn = false;
  const slotOffHF = driveSlotHF();
  check('rmhudflash: gate OFF slot win color is static gold on every step and resets at expiry',
    slotOffHF.length > 2 && slotOffHF.slice(0, -1).every(c => c === GOLD) && slotOffHF[slotOffHF.length - 1] === RESET,
    'colors=' + [...new Set(slotOffHF)].join(','));
  check('rmhudflash: gate OFF slot win flash timer drains to expiry',
    G.SLOT.winFlashT <= 0, 'winFlashT=' + G.SLOT.winFlashT);
  const loyalOffHF = driveLoyalHF();
  check('rmhudflash: gate OFF loyalty glow is static on every step and clears at expiry',
    loyalOffHF.length > 2 && loyalOffHF.slice(0, -1).every(s => s === GLOW) && loyalOffHF[loyalOffHF.length - 1] === 'none',
    'shadows=' + [...new Set(loyalOffHF)].join(' | '));
  check('rmhudflash: gate OFF loyalty flash timer drains to expiry',
    G.LOYAL.flashT <= 0, 'flashT=' + G.LOYAL.flashT);
  /* cleanup */
  G.P.traumaOn = saveTraumaHF; G.P.dead = saveDeadHF;
  G.SLOT.playing = savePlayingHF; G.SLOT.spinning = saveSpinningHF; G.SLOT.winFlashT = 0;
  G.LOYAL.flashT = 0; G.LOYAL.stingQ.length = 0;
  G.slotWinEl.style.color = RESET; G.loyalChipEl.style.boxShadow = 'none';
  G.player.position.set(savePosHF.x, savePosHF.y, savePosHF.z); G.player.rotation.y = savePosHF.ry;
  check('rmhudflash: cleanup restores traumaOn, dead, slot state, timers, styles, and player position',
    G.P.traumaOn === saveTraumaHF && G.P.dead === saveDeadHF && G.SLOT.playing === savePlayingHF
    && G.SLOT.winFlashT === 0 && G.LOYAL.flashT === 0
    && G.slotWinEl.style.color === RESET && G.loyalChipEl.style.boxShadow === 'none'
    && G.player.position.x === savePosHF.x && G.player.position.z === savePosHF.z,
    'on=' + G.P.traumaOn + ' playing=' + G.SLOT.playing);
  check('rmhudflash: the run leaves zero console errors/warnings',
    consoleProblems.length === probsHF, consoleProblems.slice(probsHF).join(' | '));
}

/* REDUCED MOTION v9: the two casino win glows (the roulette wheel-top
   emissive glow in roulUpdate and the dice-face emissive glow in
   diceUpdate) follow the P.traumaOn gate as v1-v5, v7 and v8. When the
   gate is off, each holds its static base for the same window, then
   returns to 0 exactly as before, and no-preference users see the
   identical oscillations. */
{
  const probsGL = consoleProblems.length;
  const linesGL = html.split('\n');
  const lineHasGL = sub => linesGL.filter(l => l.includes(sub)).length;
  check('rmglow: REDUCED MOTION v9 header is present exactly once in the game source',
    (html.split('/* REDUCED MOTION v9: the casino win glows').length - 1) === 1,
    'n=' + (html.split('/* REDUCED MOTION v9: the casino win glows').length - 1));
  check('rmglow: REDUCED MOTION v9 is mentioned exactly 4 times (header x2, both gate lines)',
    (html.split('REDUCED MOTION v9').length - 1) === 4,
    'n=' + (html.split('REDUCED MOTION v9').length - 1));
  check('rmglow: roulette gate line is present exactly once in the game source',
    (html.split('roulTopMat.emissiveIntensity = CASINOROUL.flashT > 0 ? (!P.traumaOn ? 0.35 :').length - 1) === 1,
    'n=' + (html.split('roulTopMat.emissiveIntensity = CASINOROUL.flashT > 0 ? (!P.traumaOn ? 0.35 :').length - 1));
  check('rmglow: dice gate line is present exactly once in the game source',
    (html.split('diceMat.emissiveIntensity = CASINODICE.glowT > 0 ? (!P.traumaOn ? 0.3 :').length - 1) === 1,
    'n=' + (html.split('diceMat.emissiveIntensity = CASINODICE.glowT > 0 ? (!P.traumaOn ? 0.3 :').length - 1));
  check('rmglow: runtime exposures exist (CASINOROUL, roulUpdate, roulTopMat, CASINODICE, diceUpdate, diceMat, P, rotorGroup)',
    !!G.CASINOROUL && typeof G.roulUpdate === 'function' && !!G.roulTopMat
    && !!G.CASINODICE && typeof G.diceUpdate === 'function' && !!G.diceMat && !!G.P && !!G.rotorGroup);
  check('rmglow-pins: 50 InstancedMesh literals unchanged', lineHasGL('new THREE.InstancedMesh') === 50,
    'n=' + lineHasGL('new THREE.InstancedMesh'));
  check('rmglow-pins: 92 Math.random lines unchanged', lineHasGL('Math.random') === 92,
    'n=' + lineHasGL('Math.random'));
  check('rmglow-pins: 72 setTimeout lines unchanged', lineHasGL('setTimeout') === 72,
    'n=' + lineHasGL('setTimeout'));
  check('rmglow-pins: 2 THREE.Points objects unchanged', lineHasGL('new THREE.Points(') === 2,
    'n=' + lineHasGL('new THREE.Points('));
  check('rmglow-pins: no em dashes', !html.includes('\u2014'));
  check('rmglow-pins: no TODO markers', !/\bTODO\b/.test(html));
  /* save harness state the drives touch */
  const saveTraumaGL = G.P.traumaOn;
  const saveRoulPlayingGL = G.CASINOROUL.playing, saveRoulSpinningGL = G.CASINOROUL.spinning;
  const saveRoulFlashGL = G.CASINOROUL.flashT, saveRoulBigWinGL = G.CASINOROUL.bigWinT;
  const saveRotorYGL = G.rotorGroup.rotation.y;
  const saveDicePlayingGL = G.CASINODICE.playing, saveDiceTumblingGL = G.CASINODICE.tumbling;
  const saveDiceSettlingGL = G.CASINODICE.settling;
  const saveDiceGlowGL = G.CASINODICE.glowT, saveDiceBigWinGL = G.CASINODICE.bigWinT;
  const saveRoulEmissGL = G.roulTopMat.emissiveIntensity, saveDiceEmissGL = G.diceMat.emissiveIntensity;
  function driveRoulGL() {
    const vals = [];
    G.CASINOROUL.playing = true; G.CASINOROUL.spinning = false; G.CASINOROUL.bigWinT = 0;
    G.CASINOROUL.flashT = 2.0;
    let guard = 0;
    while (G.CASINOROUL.flashT > 0 && guard < 200) { G.roulUpdate(0.05); vals.push(G.roulTopMat.emissiveIntensity); guard++; }
    return vals;
  }
  function driveDiceGL() {
    const vals = [];
    G.CASINODICE.playing = true; G.CASINODICE.tumbling = false; G.CASINODICE.settling = false; G.CASINODICE.bigWinT = 0;
    G.CASINODICE.glowT = 2.0;
    let guard = 0;
    while (G.CASINODICE.glowT > 0 && guard < 200) { G.diceUpdate(0.05); vals.push(G.diceMat.emissiveIntensity); guard++; }
    return vals;
  }
  /* runtime, gate ON: both glows oscillate, then return to 0 on expiry */
  G.P.traumaOn = true;
  const roulOnGL = driveRoulGL();
  check('rmglow: gate ON roulette glow oscillates (max > 0.45, distinct values > 3)',
    Math.max(...roulOnGL) > 0.45 && new Set(roulOnGL).size > 3,
    'max=' + Math.max(...roulOnGL) + ' distinct=' + new Set(roulOnGL).size);
  check('rmglow: gate ON roulette glow ends at 0 with the timer drained',
    roulOnGL[roulOnGL.length - 1] === 0 && G.CASINOROUL.flashT <= 0,
    'last=' + roulOnGL[roulOnGL.length - 1] + ' flashT=' + G.CASINOROUL.flashT);
  const diceOnGL = driveDiceGL();
  check('rmglow: gate ON dice glow oscillates (max > 0.4, distinct values > 3)',
    Math.max(...diceOnGL) > 0.4 && new Set(diceOnGL).size > 3,
    'max=' + Math.max(...diceOnGL) + ' distinct=' + new Set(diceOnGL).size);
  check('rmglow: gate ON dice glow ends at 0 with the timer drained',
    diceOnGL[diceOnGL.length - 1] === 0 && G.CASINODICE.glowT <= 0,
    'last=' + diceOnGL[diceOnGL.length - 1] + ' glowT=' + G.CASINODICE.glowT);
  /* runtime, gate OFF: static bases hold every step, expiry returns to 0 */
  G.P.traumaOn = false;
  const roulOffGL = driveRoulGL();
  check('rmglow: gate OFF roulette glow is exactly 0.35 on every step before expiry and 0 at expiry',
    roulOffGL.length > 2 && roulOffGL.slice(0, -1).every(v => v === 0.35) && roulOffGL[roulOffGL.length - 1] === 0,
    'vals=' + [...new Set(roulOffGL)].join(','));
  check('rmglow: gate OFF roulette glow timer drains to expiry',
    G.CASINOROUL.flashT <= 0, 'flashT=' + G.CASINOROUL.flashT);
  const diceOffGL = driveDiceGL();
  check('rmglow: gate OFF dice glow is exactly 0.3 on every step before expiry and 0 at expiry',
    diceOffGL.length > 2 && diceOffGL.slice(0, -1).every(v => v === 0.3) && diceOffGL[diceOffGL.length - 1] === 0,
    'vals=' + [...new Set(diceOffGL)].join(','));
  check('rmglow: gate OFF dice glow timer drains to expiry',
    G.CASINODICE.glowT <= 0, 'glowT=' + G.CASINODICE.glowT);
  /* cleanup */
  G.P.traumaOn = saveTraumaGL;
  G.CASINOROUL.playing = saveRoulPlayingGL; G.CASINOROUL.spinning = saveRoulSpinningGL;
  G.CASINOROUL.flashT = saveRoulFlashGL; G.CASINOROUL.bigWinT = saveRoulBigWinGL;
  G.rotorGroup.rotation.y = saveRotorYGL;
  G.CASINODICE.playing = saveDicePlayingGL; G.CASINODICE.tumbling = saveDiceTumblingGL;
  G.CASINODICE.settling = saveDiceSettlingGL;
  G.CASINODICE.glowT = saveDiceGlowGL; G.CASINODICE.bigWinT = saveDiceBigWinGL;
  G.roulTopMat.emissiveIntensity = saveRoulEmissGL; G.diceMat.emissiveIntensity = saveDiceEmissGL;
  check('rmglow: cleanup restores traumaOn, roulette state, rotor rotation, dice state, and both emissive values',
    G.P.traumaOn === saveTraumaGL && G.CASINOROUL.playing === saveRoulPlayingGL
    && G.CASINOROUL.spinning === saveRoulSpinningGL && G.CASINOROUL.flashT === saveRoulFlashGL
    && G.CASINOROUL.bigWinT === saveRoulBigWinGL && G.rotorGroup.rotation.y === saveRotorYGL
    && G.CASINODICE.playing === saveDicePlayingGL && G.CASINODICE.tumbling === saveDiceTumblingGL
    && G.CASINODICE.settling === saveDiceSettlingGL && G.CASINODICE.glowT === saveDiceGlowGL
    && G.CASINODICE.bigWinT === saveDiceBigWinGL
    && G.roulTopMat.emissiveIntensity === saveRoulEmissGL && G.diceMat.emissiveIntensity === saveDiceEmissGL,
    'on=' + G.P.traumaOn + ' roulPlaying=' + G.CASINOROUL.playing + ' dicePlaying=' + G.CASINODICE.playing);
  check('rmglow: the run leaves zero console errors/warnings',
    consoleProblems.length === probsGL, consoleProblems.slice(probsGL).join(' | '));
}

/* ---------- zero console errors ---------- */
check('boot+tests: zero console errors/warnings in stub env',
  consoleProblems.length === 0, consoleProblems.slice(0, 3).join(' | '));

console.error = origErr; console.warn = origWarn;
console.log(failures === 0 ? 'SMOKE RESULT: ALL GREEN' : 'SMOKE RESULT: ' + failures + ' FAILURES');
process.exit(failures === 0 ? 0 : 1);
